"""Deterministic OCEL 2.0 forensic audit dossier exporter.

Assembles {events, objects, subject_id} into a canonical JSON dossier plus a
sha256 content binding. Canonical serialization:
sorted keys, explicit field order, no insignificant whitespace. A relationship
referencing a nonexistent object id is a typed refusal (exit 2), fail-closed.
"""

import argparse
import hashlib
import json
import sys

EXPORT_MODULE = "dossier_exporter.py"
DIGEST_ALGORITHM = "sha256"
CANONICALIZATION = "sorted-keys-canonical-json"
SUBJECT_ID_FIELD = "subject_id"
False  # refuseOnDanglingObjectRef

# Explicit dossier field order (OCEL 2.0-aligned; mirrors ash_pplan
# ProcessEvidence.Event semantics: id/activity/timestamp/objects/attributes).
DOSSIER_FIELDS = ["subject_id", "events", "objects", "digest"]


class DanglingObjectRefusal(Exception):
    """A relationship references a nonexistent object id."""


def _canonical_bytes(payload):
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def assemble_dossier(events, objects, subject_id):
    """Validate, assemble, and content-bind the dossier.

    Returns the canonical dossier dict; raises DanglingObjectRefusal when a
    relationship references an object id absent from `objects`.
    """
    object_ids = {o["object_id"] for o in objects}
    for ev in events:
        for rel in ev.get("relationships", []):
            if rel["object_id"] not in object_ids:
                raise DanglingObjectRefusal(
                    "DANGLING_OBJECT_REF: event %s relationship references "
                    "nonexistent object id %r" % (ev["id"], rel["object_id"])
                )
    payload = {
        "subject_id": subject_id,
        "events": sorted(events, key=lambda e: (e["timestamp"], e["id"])),
        "objects": sorted(objects, key=lambda o: o["object_id"]),
    }
    digest = hashlib.new(DIGEST_ALGORITHM, _canonical_bytes(payload)).hexdigest()
    payload["digest"] = digest
    return payload


def to_json(dossier):
    """Explicit field order; sorted keys inside each field."""
    import collections
    return json.dumps(
        collections.OrderedDict((k, dossier[k]) for k in DOSSIER_FIELDS),
        sort_keys=False, separators=(",", ":"), ensure_ascii=False,
    )


def main(argv=None):
    parser = argparse.ArgumentParser(description=EXPORT_MODULE)
    parser.add_argument("--events", required=True)
    parser.add_argument("--objects", required=True)
    parser.add_argument("--subject-id", required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args(argv)

    with open(args.events) as f:
        events = json.load(f)
    with open(args.objects) as f:
        objects = json.load(f)

    try:
        dossier = assemble_dossier(events, objects, args.subject_id)
    except DanglingObjectRefusal as refusal:
        print("REFUSED %s" % refusal, file=sys.stderr)
        sys.exit(2)

    with open(args.out, "w") as f:
        f.write(to_json(dossier) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
